from pathlib import Path
import json

lab = json.loads(
    Path("assets/datasets/movielens/recommendation_evaluation_lab.json").read_text()
)

for name in ["mmr1", "mmr0.75", "mmr0.5"]:
    print(name, lab["scorecards"][name]["warm"], lab["diversity"][name])
for key in ["neural50:user_cf:recall", "mmr0.5:mmr1:recall"]:
    b = lab["paired"][key]["bootstrap"]
    print(key, b["mean"], b["low"], b["high"])
